          "name": "Not found",
          "secure": false,
          "value": [
            {
              "value": "(function execute() {\n    if (vaVars.query_search)\n        return gs.getMessage(\"I'm sorry, I wasn't able to find anything that matches this request, but your questions are helping me learn.\");\n    else\n        return gs.getMessage(\"I'm sorry, I wasn't able to find anything that matches this request.\");\n})()\n",
              "mode": "script"
            }
          ],
          "applicability": {
            "mode": "query",
            "value": ""
          },
          "requestFeedback": true
        },
        "d1d57d8e853649c6acedd11991054235": {
          "id": "d1d57d8e853649c6acedd11991054235",
          "stepType": "ImageOutput",
          "name": "Image",
          "url": {
            "value": "(function execute() {\n    /* Return a quoted string.  For example:\n\n       if (vaInputs.first_name == 'Bill') {\n           return gs.getMessageLang(\"hi there {0}\", vaContext.getRequesterLang(), [vaInputs.first_name]);\n       } else {\n           return gs.getMessageLang(\"how are you {0}\", vaContext.getRequesterLang(), [vaInputs.last_name]);\n       }\n    */\n    return vaVars.baseUri + vaVars.image;\n})()\n",
            "mode": "script"
          },
          "altText": {
            "value": "",
            "mode": "simple"
          },
          "variableId": "",
          "applicability": {
            "mode": "script",
            "value": "(function execute() {\n\n    return vaVars.catalog_item_id != '' && vaInputs.search == '' && vaVars.image_not_shown;\n    \n})()\n"
          }
        },
        "4a0853de7a8a43bba1158f70ddaefbe4": {
          "id": "4a0853de7a8a43bba1158f70ddaefbe4",
          "name": "Set catalog item variables",
          "script": "(function execute() {\n    if(vaInputs.catalog_item_id == null && vaVars.catalog_item_id != null)\n      vaInputs.catalog_item_id = vaVars.catalog_item_id;\n    else if(vaVars.catalog_item_id == null && vaInputs.catalog_item_id != null)\n     vaVars.catalog_item_id = vaInputs.catalog_item_id;\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "e89b222dc45a4559a059a73ca834e13a": {
